// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { CSPProvider } from "@/registry/erbium/ui/csp-provider";

import ExternalStylesExample, {
  defaultProps as ExternalStylesDefaults,
} from "./variants/external-styles";



import ShowcaseExample from "./variants/showcase";



const meta = {
  component: CSPProvider,
  parameters: {
    docs: {
      description: {
        component: "## Usage

Configures inline style and script tags rendered by Base UI components. Import from `@/registry/erbium/ui/csp-provider`.

Wrap your application with `<CSPProvider nonce={nonceFromServer}>` when your CSP requires a nonce. Generate a fresh nonce on the server for each response and include the same value in the CSP header. The provider does not configure the header or authorize inline style attributes.

Alternatively, use `disableStyleElements` with Erbium's global stylesheet, which includes Base UI's scrollbar-hiding rules. Storybook and the docs previews use this configuration. This option does not disable inline scripts; opt-in scripts still require a nonce under a strict CSP.

See [Base UI CSP Provider](https://base-ui.com/react/utils/csp-provider) for server configuration and limitations.

## Base UI documentation

Explore the underlying primitives and their API reference.

- [CSP Provider](https://base-ui.com/react/utils/csp-provider)",
      },
    },
    layout: "centered",
  },
} satisfies Meta<typeof CSPProvider>;

export default { ...meta, title: "Providers/Csp Provider",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj<typeof meta>;

export const ExternalStyles: Story = {
  args: ExternalStylesDefaults,
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: "import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { ScrollArea } from "@/registry/erbium/ui/scroll-area";
import type * as React from "react";

export const defaultProps = {
  disableStyleElements: true,
} satisfies React.ComponentProps<typeof CSPProvider>;

export default function CspProviderExternalStylesExample(
  args: React.ComponentProps<typeof CSPProvider> = defaultProps,
) {
  return (
    <CSPProvider {...args}>
      <ScrollArea className="h-40 w-72" aria-label="CSP provider example">
        {Array.from({ length: 12 }, (_, index) => (
          <p key={index} className="p-3">
            Scrollable item {index + 1}
          </p>
        ))}
      </ScrollArea>
    </CSPProvider>
  );
}
" },
    },
  },
  render: ExternalStylesExample,
};

export const Showcase: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: "import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { ScrollArea } from "@/registry/erbium/ui/scroll-area";

export default function CspProviderShowcaseExample() {
  return (
    <CSPProvider disableStyleElements>
      <ScrollArea className="h-40 w-72" aria-label="Scrollable example">
        {Array.from({ length: 12 }, (_, index) => (
          <p key={index} className="p-3">
            Scrollable item {index + 1}
          </p>
        ))}
      </ScrollArea>
    </CSPProvider>
  );
}
" },
    },
  },
  render: ShowcaseExample,
};

